package com.loopers.interfaces.consumer;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.clients.producer.*;import org.apache.kafka.common.TopicPartition;import org.apache.kafka.common.serialization.StringSerializer;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class KafkaRedeliveryExperimentTest{@Test void uncommittedSameOffsetRedeliversButEffectIsOnce()throws Exception{try(KafkaExperimentSupport k=new KafkaExperimentSupport()){String t="redelivery-w6",g="w6-redelivery";k.topic(t,1);Properties p=new Properties();p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG,k.broker.getBootstrapServers());p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,StringSerializer.class);try(KafkaProducer<String,String>producer=new KafkaProducer<>(p)){producer.send(new ProducerRecord<>(t,"order-1","event-1")).get();}Set<String>ledger=new HashSet<>();int deliveries=0;try(KafkaConsumer<String,String>first=k.consumer(g,"A")){first.subscribe(List.of(t));ConsumerRecord<String,String>r=one(first);deliveries++;ledger.add(r.value());}try(KafkaConsumer<String,String>second=k.consumer(g,"A")){second.subscribe(List.of(t));ConsumerRecord<String,String>r=one(second);deliveries++;ledger.add(r.value());second.commitSync(Map.of(new TopicPartition(t,r.partition()),new OffsetAndMetadata(r.offset()+1)));}assertThat(deliveries).isEqualTo(2);assertThat(ledger).hasSize(1);}}private ConsumerRecord<String,String>one(KafkaConsumer<String,String>c){for(int i=0;i<100;i++){ConsumerRecords<String,String>rs=c.poll(Duration.ofMillis(100));if(!rs.isEmpty())return rs.iterator().next();}throw new AssertionError("no record");}}
